head.b:skin:
body { background-color: #141414; color: white; margin: 0; padding: 0; font-family: system-ui, -apple-system, sans-serif; }
.post-body img { max-width: 100%; border-radius: 4px; margin-bottom: 1rem; }
.post-body p { margin-bottom: 1rem; line-height: 1.6; }
.post-body h2 { font-size: 1.5rem; font-weight: bold; margin-top: 2rem; margin-bottom: 1rem; }
.post-body h3 { font-size: 1.25rem; font-weight: bold; margin-top: 1.5rem; margin-bottom: 0.5rem; }

b:if.script:
             document.addEventListener("DOMContentLoaded", function() {
               var postBody = document.getElementById("post-body");
               var videoUrlDiv = document.getElementById("video-url");
               var watchBtn = document.getElementById("watch-now-btn");
               var timerDisplay = document.getElementById("timer-display");
               var timerCount = document.getElementById("timer-count");
               var thumbnailContainer = document.getElementById("thumbnail-container");
               var videoContainer = document.getElementById("video-container");
               var playOverlay = document.getElementById("play-overlay");
               var postThumbnail = document.getElementById("post-thumbnail");

               // Check if user has added 
inside post body
               if (videoUrlDiv && watchBtn) {
                 // Show the play button overlay
                 playOverlay.classList.remove("hidden");

                 var videoUrl = videoUrlDiv.innerText.trim();

                 watchBtn.addEventListener("click", function() {
                   watchBtn.classList.add("hidden");
                   timerDisplay.classList.remove("hidden");

                   var timeLeft = 5;
                   timerCount.innerText = timeLeft;

                   var countdown = setInterval(function() {
                     timeLeft--;
                     timerCount.innerText = timeLeft;

                     if (timeLeft <= 0) {
                       clearInterval(countdown);

                       // Hide thumbnail, show video
                       thumbnailContainer.classList.add("hidden");
                       videoContainer.classList.remove("hidden");

                       // Create iframe
                       var iframe = document.createElement("iframe");
                       iframe.className = "absolute inset-0 w-full h-full";
                       iframe.setAttribute("allow", "autoplay; fullscreen");
                       iframe.setAttribute("allowfullscreen", "true");

                       // Handle Google Drive vs YouTube
                       if (videoUrl.includes("drive.google.com/file/d/")) {
                         var match = videoUrl.match(/d\/([a-zA-Z0-9_-]+)/);
                         if (match) {
                           iframe.src = "https://drive.google.com/file/d/" + match[1] + "/preview";
                         }
                       } else if (videoUrl.includes("youtube.com") || videoUrl.includes("youtu.be")) {
                         var ytId = "";
                         if (videoUrl.includes("youtu.be/")) {
                           ytId = videoUrl.split("youtu.be/")[1].split("?")[0];
                         } else if (videoUrl.includes("watch?v=")) {
                           ytId = videoUrl.split("watch?v=")[1].split("&")[0];
                         }
                         iframe.src = "https://www.youtube.com/embed/" + ytId + "?autoplay=1&rel=0";
                       } else {
                         iframe.src = videoUrl;
                       }

                       videoContainer.innerHTML = "<div class='relative pt-[56.25%] w-full'></div>";
                       videoContainer.firstChild.appendChild(iframe);
                     }
                   }, 1000);
                 });
               } else if (postThumbnail) {
                  // If no video URL is provided, show thumbnail normally without play button
                  postThumbnail.classList.remove("opacity-60");
               }
             });
